"""Declared dimensional transitions on a mouth-free original Street span.

Sources remain the original ordered controls. GN reads the actual edge widths,
prepares the same bounded quintic taper used by connected corridors, and emits
direct quads. This opt-in primitive does not relax any path or cell checks.
"""
from . import curved_junction_nodes as boundary, curved_taper_placement_nodes
import bpy
import hashlib

c = boundary.c


def prepare(g, inp, addressed, span, start_cut, end_cut):
    """Bind one validated original span to its finite dimensional declarations."""
    sources, mapping = inp.outputs['Sources'], inp.outputs['Mapping']
    read = lambda key: c._read(g, mapping, 'st_ps_'+key, span, 'INT')
    first = c.V(g, addressed.outputs['Curve First'])
    last = c.V(g, addressed.outputs['Curve Last'])
    i = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    raw = g.setpos(c._line(g, c.bounded(g, last-first+1., 2., c.MAX_CONTROLS)),
        c._sample(g, sources, g.position(), read('start')+first+i, 'FLOAT_VECTOR'))
    for key, kind in (('st_width', 'FLOAT'), ('st_offset', 'FLOAT'), ('st_section_id', 'INT')):
        raw = g.store(raw, key, boundary._edge_sample(g, sources, c.named(g, key, kind),
                      read('edge_start')+first+i, kind), 'EDGE', kind)
    declarations = c._select(g, inp.outputs['Transitions'],
                            g.math('COMPARE', c.named(g, 'st_cd_span', 'INT'), span))
    declarations = c._store(g, declarations, 'st_cd_vertex',
                           c.named(g, 'st_cd_vertex', 'INT')-first, 'INT')
    identity = g.math('COMPARE', c.named(g, 'st_cd_street_id', 'INT'), read('street_id'))
    identity = identity*g.math('GREATER_THAN', c.named(g, 'st_cd_source_id', 'INT'), -.5)
    kind = c.named(g, 'st_cd_source_kind', 'INT')
    # Provenance only: SymLane, SideLane, deferred Intersection, AuthoredTransition.
    identity = identity*g.math('GREATER_THAN', kind, -.5)*g.math('LESS_THAN', kind, 3.5)
    present = 1.
    for key in ('span', 'street_id', 'source_id', 'source_kind'):
        attr = g.node('GeometryNodeInputNamedAttribute'); attr.data_type = 'INT'
        attr.inputs['Name'].default_value = 'st_cd_'+key
        present = present*c.V(g, attr.outputs['Exists'])
    has_rows = g.math('GREATER_THAN', c._count(g, declarations), .5)
    identity = c.choose(g, has_rows, c._stat(g, declarations, identity*present), 1.)
    table = g.node('GeometryNodeGroup', 'Bounded taper on original controls and Section seams')
    table.node_tree = curved_taper_placement_nodes.prepare(interpolation=True)
    for key, value in (('Source', raw), ('Transitions', declarations),
                       ('First Control', read('first')-first), ('Last Control', read('last')-first),
                       ('Start Cut', start_cut), ('End Cut', end_cut),
                       ('Interpolation', addressed.outputs['Interpolation'])):
        g.bind(value, table.inputs[key])
    valid = identity*c.V(g, table.outputs['Valid'])
    valid = valid*g.math('LESS_THAN', g.math('ABSOLUTE',
        c.V(g, table.outputs['Length'])-c.V(g, addressed.outputs['Length'])), 2e-4)
    return table, valid


def dispatch(original):
    """Keep existing constant runs exact; select tapers by declared span ID."""
    from . import curved_standalone_nodes
    name = original.name+' / Authored dimensional run dispatch v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    is_boundary = original.name.startswith('Prochitecture Streets / Category-bounded profiled run v1')
    if 'Exact or smooth' not in original.name:raise ValueError('Dimensional runs need mode-aware input')
    g = c.Graph(name)
    sockets=[s for s in original.interface.items_tree if s.item_type=='SOCKET']
    for s in sockets:g.socket(s.name,s.socket_type,s.in_out,default=getattr(s,'default_value',None))
    g.socket('Transitions','NodeSocketGeometry')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    old=g.node('GeometryNodeGroup','Preserve existing constant-dimension results');old.node_tree=original
    new=g.node('GeometryNodeGroup','Declared original dimensional run')
    new.node_tree=curved_standalone_nodes.street(boundary_span=is_boundary,interpolation=True,
        selection_cuts='Declared selection trims' in original.name,dimensions=True)
    for s in sockets:
        if s.in_out=='INPUT':
            g.bind(inp.outputs[s.name],old.inputs[s.name]);g.bind(inp.outputs[s.name],new.inputs[s.name])
    g.bind(inp.outputs['Transitions'],new.inputs['Transitions'])
    rows=inp.outputs['Boundary Runs' if is_boundary else 'Standalone Streets']
    span=c._read(g,rows,'st_br_span' if is_boundary else 'st_fs_span',inp.outputs['Index'],'INT')
    matching=c._select(g,inp.outputs['Transitions'],g.math('COMPARE',c.named(g,'st_cd_span','INT'),span))
    use_new=g.math('GREATER_THAN',c._count(g,matching),.5)
    for s in sockets:
        if s.in_out!='OUTPUT':continue
        kind='GEOMETRY' if s.socket_type=='NodeSocketGeometry' else 'BOOLEAN'
        if s.socket_type not in ('NodeSocketGeometry','NodeSocketBool'):raise ValueError('Unexpected run output')
        g.bind(c.choose(g,use_new,new.outputs[s.name],old.outputs[s.name],kind),out.inputs[s.name])
    g.g['st_authored_dimension_runs']=1
    return g.g


def replace_saved(roots):
    """Upgrade shared run consumers, forwarding declarations through callers."""
    from .curved_quad_fair_nodes import assign_group
    memo={};visiting=set();copies=[];changes=[]
    def visit(tree):
        if tree in memo:return memo[tree]
        if tree in visiting:raise ValueError('Cycle in dimensional run builder references')
        if tree.get('st_authored_dimension_runs'):raise ValueError('Dimensional run dispatch already installed')
        visiting.add(tree)
        if tree.name.startswith(('Prochitecture Streets / Unattached profiled Street v1',
                                 'Prochitecture Streets / Category-bounded profiled run v1')):
            result=dispatch(tree);changes.append(dict(original=tree.name,replacement=result.name))
        else:
            children=[(node.name,visit(node.node_tree)) for node in tree.nodes if node.type=='GROUP' and node.node_tree]
            children=[(name,child) for name,child in children if child!=tree.nodes[name].node_tree]
            refs=[(key,visit(value)) for key,value in tree.items() if isinstance(value,bpy.types.NodeTree)]
            refs=[(key,value) for key,value in refs if value!=tree[key]]
            result=tree.copy() if children or refs else tree
            if result!=tree:
                result.use_fake_user=False;copies.append((tree,result))
                for name,child in children:
                    node=result.nodes[name];assign_group(node,child)
                    if 'Transitions' in node.inputs and not node.inputs['Transitions'].is_linked:
                        if not any(s.item_type=='SOCKET' and s.in_out=='INPUT' and s.name=='Transitions'
                                   for s in result.interface.items_tree):
                            result.interface.new_socket(name='Transitions',in_out='INPUT',socket_type='NodeSocketGeometry')
                        inp=next((n for n in result.nodes if n.type=='GROUP_INPUT'),None)
                        if inp is None:inp=result.nodes.new('NodeGroupInput')
                        result.links.new(inp.outputs['Transitions'],node.inputs['Transitions'])
                for key,value in refs:result[key]=value
        visiting.remove(tree);memo[tree]=result;return result
    results=[visit(tree) for tree in roots]
    if len(changes)!=2:raise ValueError('Expected shared standalone and boundary-run constructors')
    for old,new in copies:
        name=old.name;old.name='Before dimensional run builder / '+hashlib.sha256(name.encode()).hexdigest()[:16]
        new.name=name
        if new.name!=name:raise ValueError('Lost shared builder entry point')
    return results,changes
